import sys, json, re, datetime, signal, time

# THE MODEL READS ITS OWN WALL (curator, GH #893). Three tools, served inside the
# hive and answered out of its ledger alone -- no model, no embedding, no store
# outside this hive:
#
#   history_search   a phrase, an exact text or a regular expression over the
#                    wall, newest first, each hit with its block id `#<12 hex>`,
#                    its turn, its time and an excerpt around the match.
#   history_read     one block by its id, or every block of a turn range, whole.
#                    Over `read_budget` it refuses with `too_large` and the size;
#                    it never shortens (OR-KY-H1: a model asks narrower, it does
#                    not read half a block).
#   history_outline  the sessions of the wall with their turn ranges, and the
#                    topics the `topic` marks opened and closed (OR-KY-H2,
#                    OR-KY-71).
#
# THE WALL IS THIS HIVE'S OWN. `./ledger` is the one store this cell reaches
# (`write_surface` internal) and it holds the calls of ONE model, so a model
# never reads another model's wall: an id that is not on this wall is
# `not_found`, whatever other ledger may hold it.
#
# EVERY READ IS BOUNDED (contract review I-1). A search reads the wall page by
# page (`page_rows`), newest first, and stops at the page that fills its
# `limit`, at `scan_budget` rows, or when `time_budget_ms` since the call has
# run out -- a match that backtracks without end is interrupted by SIGALRM, so
# the answer always comes before the runner's `external_timeout_ms` would kill
# the child (whose `script_timeout` carries no route: the call would stay
# unanswered). A range read ends at the last row of its last turn, and one
# whose rows cannot fit is refused before its bodies are fetched. An outline
# reads the newest `scan_budget` rows.
#
# THE MODEL'S OWN HISTORY CALLS ARE NO HITS (contract review I-5). They stand on
# the wall like every round (the curator writes them, OR-KY-62), but a search
# that found them would show the excerpts of an earlier answer before their
# sources, and a range would carry earlier reads over again. A `history_*`
# `tool_call`, a `tool_result` under its id and a `tool_result` whose text is
# one of this cell's answers are left out of searches, neighbours and ranges;
# by its id each is read whole.
#
# The call arrives on `in_history_call` in the dispatcher's shape (one
# `tool_call` turn, the arguments as its text, `hop.tool_call_id`,
# `hop.tool_name`) and the answer leaves on `tool_result` in the shape every
# tool answers in (collector "What a tool result may carry"): one `tool_result`
# turn under the call id, its text a JSON object. A refusal is an answer too --
# `error` names the code and `hop.error_code` carries it -- so the round the call
# belongs to is always complete.
#
# THE SCHEMAS ARE NOT HERE. What a model is offered is the curator's menu answer
# (`HISTORY_SCHEMAS`, spliced into `CURATOR_OFFER` in `./schemas`, OR-KY-G1,
# OR-KY.T.1); `ARGS` below is what this cell reads of a call, and a lock holds
# the two to one set of names.
doc = json.load(sys.stdin)
d = doc.get("body") or {}
envelope = doc.get("envelope") or {}
P = doc.get("params") or {}
header = envelope.get("header") or {}
hop = header.get("hop") or {}
ctx = header.get("context") or {}


def _int(key, default):
    v = P.get(key, default)
    if v is None or (isinstance(v, str) and not v.strip()):
        return default
    return int(float(v))


# The knobs. The literal beside each name is the shipped default, the same
# number `params` and `contract.settings` carry.
READ_BUDGET = _int("read_budget", 40000)
SCAN_BUDGET = max(1, _int("scan_budget", 5000))
TIME_BUDGET_MS = _int("time_budget_ms", 3000)
PAGE_ROWS = max(1, _int("page_rows", 250))

ME = "curator-history"
FMT = "%Y-%m-%dT%H:%M:%S.%fZ"
LIMIT_DEFAULT = 8
LIMIT_MAX = 20
CONTEXT_MAX = 2
EXCERPT = 120
PATTERN_MAX = 200
# The newest sessions an outline names; older ones are counted, not listed.
OUTLINE_SESSIONS = 100
# A turn range whose raw text (`blocks.chars`) is over this many read budgets
# is refused before a body is fetched. The canonical JSON a read measures is
# never shorter than the text, so only the model's own history answers could
# bring such a range back under the budget -- and a narrower range does that.
RAW_FACTOR = 10
# The least time one page of a search gets to match, even when the budget was
# spent before it began (a busy host): the search then stops after that page
# instead of answering with nothing it could have found.
SLICE_MIN_MS = 100
# Neighbour rows read beyond `context` on each side, so the model's own history
# pairs can be left out without leaving a gap.
NEAR_SPARE = 4
MODES = ("exact", "phrase", "regex")
MOVES = ("start", "continue", "end")
# The kinds a wall row can carry (`./intake` `kinds_of`); `system`, `summary`,
# `pin` and `view` blocks live in the ledger but never on the wall.
WALL_KINDS = ("user", "assistant", "peer", "advice", "delegation", "tool_call",
              "tool_result", "recall", "brief")
ARGS = {
    "history_search": ("query", "mode", "since", "until", "kinds", "limit", "context"),
    "history_read": ("id", "from_turn", "to_turn"),
    "history_outline": ("since",),
}
WALL_COLS = ["seq", "session_id", "turn_id", "kind", "hash", "final", "at"]
HEX = re.compile(r"^[0-9a-f]{12,64}$")

try:
    _MEM
except NameError:
    # The last `marks.seq` this child minted (resident runner). A restarted
    # child starts from the clock again; `seq` is order, not identity (OR-KY-61).
    _MEM = {"seq": 0}


def emit(msgs):
    sys.stdout.write(json.dumps(msgs))
    sys.exit(0)


def park(reason=""):
    if reason:
        sys.stderr.write("curator/history: %s\n" % reason)
    emit([])


def now():
    return datetime.datetime.now(datetime.timezone.utc).strftime(FMT)


def now_ms():
    return int(time.time() * 1000)


def next_seq():
    """One `marks.seq`: microseconds since the epoch like `wall.seq`, strictly
    above anything this child minted before (OR-KY-61)."""
    base = int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000000)
    base = max(base, _MEM["seq"] + 1)
    _MEM["seq"] = base
    return base


def short_id(h):
    return "#" + str(h or "")[:12]


def lstore(ops, phase, call, reason):
    """One message to `./ledger`. Every key the edge reads is always present
    (a failed CEL modifier skips the edge). `cur_call` carries the tool call
    id and `cur_reason` the call itself across the store's answer."""
    return {"header": {"route": "lstore", "phase": phase, "reply_cell": ME,
                       "cur_call": call, "cur_reason": reason},
            "messages": [{"origin": "assistant", "type": "tool_call", "id": cid,
                          "text": json.dumps(args)} for cid, args in ops]}


def legs(body):
    """The answer of a store message by tool_call id: payload and error code,
    for a bundle (`results[]`) and for a single op alike."""
    out = {}
    for m in body.get("messages") or []:
        if not isinstance(m, dict):
            continue
        try:
            payload = json.loads(m.get("text") or "null")
        except Exception:
            payload = None
        out[str(m.get("id") or "")] = {"payload": payload, "error_code": ""}
    results = body.get("results")
    if isinstance(results, list):
        for r in results:
            if isinstance(r, dict):
                leg = out.setdefault(str(r.get("tool_call_id") or ""),
                                     {"payload": None, "error_code": ""})
                leg["error_code"] = str(r.get("error_code") or "")
    elif len(out) == 1:
        next(iter(out.values()))["error_code"] = str(hop.get("error_code") or "")
    return out


def rows(lg, cid):
    p = (lg.get(cid) or {}).get("payload")
    return p if isinstance(p, list) else []


def failed(lg):
    return sorted(cid for cid, leg in lg.items() if leg["error_code"])


def sel(table, columns, where=None, order=None, limit=None):
    a = {"operation": "select", "table": table, "columns": columns}
    if where:
        a["where"] = where
    if order:
        a["order_by"] = [{"col": c, "dir": o} for c, o in order]
    if limit:
        a["limit"] = limit
    return a


def answer(call_id, name, payload, code=""):
    """The one tool_result of a call. `code` empty = an answer, else a refusal
    whose text names the same code."""
    if code:
        payload = dict(payload)
        payload["error"] = code
    payload = dict(payload, tool=name)
    text = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return {"header": {"route": "tool_result", "tool_call_id": call_id, "tool_name": name,
                       "error_code": code},
            "messages": [{"origin": "tool", "type": "tool_result", "id": call_id,
                          "text": text}]}


def refuse(call_id, name, code, detail, extra=None):
    payload = {"detail": detail}
    payload.update(extra or {})
    emit([answer(call_id, name, payload, code)])


def element_of(body):
    try:
        el = json.loads(str(body or "null"))
    except Exception:
        return None
    return el if isinstance(el, dict) else None


def text_of(el):
    return str((el or {}).get("text") or "")


def bodies_of(lg, cid):
    return {str(r.get("hash") or ""): str(r.get("body") or "") for r in rows(lg, cid)}


def iso(value, end_of_day=False):
    """An ISO-8601 time as the wall writes it (UTC, microseconds, `Z`), or None
    when it does not read as one. A bare date is its first microsecond -- or,
    for an upper bound, its last one: `until 2026-09-28` means the whole day."""
    v = str(value or "").strip()
    if not v:
        return None
    if re.match(r"^\d{4}-\d{2}-\d{2}$", v):
        try:
            day = datetime.datetime.strptime(v, "%Y-%m-%d")
        except ValueError:
            return None
        if end_of_day:
            day = day + datetime.timedelta(days=1) - datetime.timedelta(microseconds=1)
        return day.strftime(FMT)
    if v.endswith("Z") or v.endswith("z"):
        v = v[:-1] + "+00:00"
    try:
        t = datetime.datetime.fromisoformat(v)
    except ValueError:
        return None
    if t.tzinfo is not None:
        t = t.astimezone(datetime.timezone.utc).replace(tzinfo=None)
    return t.strftime(FMT)


def norm_id(value):
    """`#abc…`, `[#abc…]` or a bare hex string -> the lower-case hex, or ''."""
    v = str(value or "").strip().strip("[]").strip().lstrip("#").strip().lower()
    return v if HEX.match(v) else ""


# ============================================================ OWN HISTORY

def tool_name_of(el):
    """The function a `tool_call` element calls ('' for any other element):
    its text is the stringified `{name, arguments}` (the llm cell's UBF)."""
    if str((el or {}).get("type") or "") != "tool_call":
        return ""
    try:
        fn = json.loads(text_of(el))
    except Exception:
        return ""
    return str(fn.get("name") or "") if isinstance(fn, dict) else ""


def is_history_answer(el):
    """A `tool_result` whose text is one of this cell's answers (`answer`
    always names its tool)."""
    if str((el or {}).get("type") or "") != "tool_result":
        return False
    t = text_of(el)
    if not t.startswith("{"):
        return False
    try:
        out = json.loads(t)
    except Exception:
        return False
    return isinstance(out, dict) and str(out.get("tool") or "").startswith("history_")


def own_history(rs, bodies):
    """The `seq`s among `rs` that are the model's own history calls and their
    answers: a `history_*` `tool_call`, a `tool_result` under the id of one of
    them, a `tool_result` that is one of this cell's answers."""
    els = [(int(r.get("seq") or 0), element_of(bodies.get(str(r.get("hash") or ""))))
           for r in rs]
    calls = {str(el.get("id") or "") for _, el in els
             if el is not None and tool_name_of(el).startswith("history_")}
    calls.discard("")
    out = set()
    for seq, el in els:
        if el is None:
            continue
        if (tool_name_of(el).startswith("history_") or is_history_answer(el)
                or (str(el.get("type") or "") == "tool_result"
                    and str(el.get("id") or "") in calls)):
            out.add(seq)
    return out


# ================================================================== MARKS

def released_hashes(marks, hashes):
    """The hashes among `hashes` TRIM has released and not pinned since: the
    `release` and `pin` marks replayed in `seq` order, the later word wins
    (OR-KY.T.13; in one block `./intake` writes the releases before the pins).
    The value is the 12 hex digits (OR-KY.T.4); a `#`, a longer prefix or the
    full hash is read too."""
    state = {}
    for m in sorted(marks, key=lambda m: int(m.get("seq") or 0)):
        ref = norm_id(m.get("value"))
        if not ref:
            continue
        for h in hashes:
            if h.startswith(ref):
                state[h] = str(m.get("kind") or "")
    return {h for h, kind in state.items() if kind == "release"}


def reread_ops(released, marks_now):
    """One `reread` mark per released block and turn (R-27-2 point 7: the
    re-read quota is counted at the end of the program). Read before written
    (OR-KY-61): a block this turn already re-read is not marked twice."""
    session = str(ctx.get("session_id") or "default")
    turn = str(ctx.get("turn_id") or "")
    have = {str(m.get("value") or "") for m in marks_now
            if str(m.get("session_id") or "") == session}
    ops = []
    for h in sorted(released):
        if h in have:
            continue
        seq = next_seq()
        ops.append(("m-%d" % seq, {"operation": "insert", "table": "marks", "row": {
            "seq": seq, "session_id": session, "turn_id": turn, "kind": "reread",
            "value": h, "at": now()}}))
    return ops


def marks_reads(turn):
    return [("r-rel", sel("marks", ["seq", "kind", "value"],
                          {"kind": {"in": ["release", "pin"]}}, [("seq", "desc")],
                          SCAN_BUDGET)),
            ("r-mine", sel("marks", ["session_id", "value"],
                           {"kind": "reread", "turn_id": turn}))]


# ================================================================== SEARCH

class Slow(BaseException):
    """The time budget ran out inside a match (SIGALRM). A BaseException, so no
    `except Exception` on the way swallows it."""


def _alarm(signum, frame):
    raise Slow()


def matcher(args):
    """The one function a search asks per text: (start, end) of the first
    match, or None. Built once per page; the pattern was checked at entry."""
    q, mode = args["query"], args["mode"]
    if mode == "exact":
        def find(text):
            at = text.find(q)
            return None if at < 0 else (at, at + len(q))
        return find
    if mode == "phrase":
        # The words in this order, any case, any spacing between them.
        rx = re.compile(r"\s+".join(re.escape(w) for w in q.split()), re.IGNORECASE)
    else:
        rx = re.compile(q)

    def find(text):
        m = rx.search(text)
        return None if m is None else (m.start(), m.end())
    return find


def excerpt(text, span=None):
    """`EXCERPT` characters on either side of the match (the head of the text
    without one), marked with `…` where it was cut."""
    if span is None:
        cut = text[:2 * EXCERPT]
        return cut + ("…" if len(text) > len(cut) else "")
    a, b = max(0, span[0] - EXCERPT), min(len(text), span[1] + EXCERPT)
    return ("…" if a > 0 else "") + text[a:b] + ("…" if b < len(text) else "")


def wall_page(args, top, n):
    """`n` wall rows at or below `seq` `top` (None: from the newest), newest
    first, inside the time bound the store can hold -- one operator per column,
    so with both bounds the store takes `until` and `inside` the rest."""
    where = {}
    if args.get("until"):
        where["at"] = {"lte": args["until"]}
    elif args.get("since"):
        where["at"] = {"gte": args["since"]}
    if top is not None:
        where["seq"] = {"lte": int(top)}
    return sel("wall", WALL_COLS, where or None, [("seq", "desc")], max(1, int(n)))


def inside(args, r):
    since = args.get("since")
    return not since or str(r.get("at") or "") >= since


def page_bundle(args, page):
    """The next page: its rows read again (at or below its newest `seq`, as
    many as it has -- the wall is append-only, so this is the same page), the
    bodies of its blocks, and the rows of the page after it."""
    seqs = [int(r.get("seq") or 0) for r in page]
    hashes = sorted({str(r.get("hash") or "") for r in page})
    left = SCAN_BUDGET - int(args["scanned"]) - len(page)
    return lstore([("s-page", wall_page(args, max(seqs), len(page))),
                   ("s-blocks", sel("blocks", ["hash", "body"], {"hash": {"in": hashes}})),
                   ("s-next", wall_page(args, min(seqs) - 1, max(1, min(PAGE_ROWS, left))))],
                  "search-page", call_id, carry(name, args))


def scan_page(args, page, bodies):
    """Match one page, newest first, into `args` (`scanned`, `total`, `hits`).
    Returns "time_budget" when the budget ran out inside it, else ""."""
    find = matcher(args)
    kinds = set(args.get("kinds") or [])
    own = own_history(page, bodies)
    left = TIME_BUDGET_MS - (now_ms() - int(args["t0"]))
    cut = ""
    prev = signal.signal(signal.SIGALRM, _alarm)
    try:
        signal.setitimer(signal.ITIMER_REAL, max(left, SLICE_MIN_MS) / 1000.0)
        try:
            for r in page:
                if not inside(args, r):
                    continue
                args["scanned"] += 1
                seq = int(r.get("seq") or 0)
                if seq in own or (kinds and str(r.get("kind") or "") not in kinds):
                    continue
                el = element_of(bodies.get(str(r.get("hash") or "")))
                if el is None:
                    continue
                text = text_of(el)
                span = find(text)
                if span is None:
                    continue
                args["total"] += 1
                if len(args["hits"]) < args["limit"]:
                    args["hits"].append({
                        "id": short_id(r.get("hash")), "seq": r.get("seq"),
                        "session_id": r.get("session_id"), "turn_id": r.get("turn_id"),
                        "at": r.get("at"), "kind": r.get("kind"),
                        "excerpt": excerpt(text, span)})
        finally:
            signal.setitimer(signal.ITIMER_REAL, 0)
    except Slow:
        cut = "time_budget"
    finally:
        signal.signal(signal.SIGALRM, prev)
    return cut


def search_payload(args):
    out = {"mode": args["mode"], "query": args["query"], "hits": args["hits"],
           "total_hits": args["total"], "scanned": args["scanned"], "limit": args["limit"],
           "truncated_scan": bool(args.get("cut_by")),
           "stopped_at_limit": bool(args.get("stopped"))}
    if args.get("cut_by"):
        out["cut_by"] = args["cut_by"]
    return out


def near_ops(hits, width):
    """The rows beside each hit in its own session, a few more than `context`
    on each side so the model's own history pairs can be left out."""
    ops = []
    for i, hit in enumerate(hits):
        where = {"session_id": str(hit.get("session_id") or "")}
        q = int(hit.get("seq") or 0)
        ops.append(("nb%d" % i, sel("wall", WALL_COLS, dict(where, seq={"lt": q}),
                                    [("seq", "desc")], width + NEAR_SPARE)))
        ops.append(("na%d" % i, sel("wall", WALL_COLS, dict(where, seq={"gt": q}),
                                    [("seq", "asc")], width + NEAR_SPARE)))
    return ops


def finish_search(args, stopped=False, cut_by=""):
    """The answer of a search whose scan is over -- after the neighbours of its
    hits, when `context` asks for them."""
    args = dict(args, stopped=stopped, cut_by=cut_by)
    if args["context"] and args["hits"]:
        emit([lstore(near_ops(args["hits"], args["context"]), "search-near", call_id,
                     carry(name, args))])
    emit([answer(call_id, name, search_payload(args))])


def neighbour(r, bodies):
    el = element_of(bodies.get(str(r.get("hash") or "")))
    return {"id": short_id(r.get("hash")), "kind": r.get("kind"),
            "turn_id": r.get("turn_id"), "excerpt": excerpt(text_of(el))}


class Refusal(Exception):
    def __init__(self, code, detail, extra=None):
        Exception.__init__(self, detail)
        self.code, self.detail, self.extra = code, detail, extra or {}


def bounded(value, default, lo, hi, name):
    if value is None or value == "":
        return default
    try:
        n = int(value)
    except (TypeError, ValueError):
        raise Refusal("bad_arguments", "`%s` is a whole number from %d to %d" % (name, lo, hi))
    return max(lo, min(hi, n))


def time_bounds(args):
    since, until = args.get("since"), args.get("until")
    out = {}
    for key, raw, end in (("since", since, False), ("until", until, True)):
        if raw in (None, ""):
            continue
        t = iso(raw, end)
        if t is None:
            raise Refusal("bad_arguments", "`%s` is an ISO-8601 time, e.g. 2026-09-28T14:00:00Z" % key)
        out[key] = t
    if out.get("since") and out.get("until") and out["since"] > out["until"]:
        raise Refusal("bad_range", "`since` lies after `until`")
    return out


def parse_search(raw):
    query = raw.get("query")
    if not isinstance(query, str) or not query.strip():
        raise Refusal("bad_arguments", "`query` names the text to find")
    mode = str(raw.get("mode") or "phrase")
    if mode not in MODES:
        raise Refusal("bad_arguments", "`mode` is one of exact, phrase, regex")
    if mode == "regex":
        if len(query) > PATTERN_MAX:
            raise Refusal("bad_pattern", "a pattern is at most %d characters" % PATTERN_MAX)
        try:
            re.compile(query)
        except re.error as e:
            raise Refusal("bad_pattern", "the pattern does not compile: %s" % e)
    kinds = raw.get("kinds")
    if kinds in (None, ""):
        kinds = []
    if isinstance(kinds, str):
        kinds = [k.strip() for k in kinds.split(",") if k.strip()]
    if not isinstance(kinds, list) or any(k not in WALL_KINDS for k in kinds):
        raise Refusal("bad_arguments", "`kinds` names block kinds out of: " + ", ".join(WALL_KINDS))
    args = {"query": query, "mode": mode, "kinds": sorted(set(kinds)),
            "limit": bounded(raw.get("limit"), LIMIT_DEFAULT, 1, LIMIT_MAX, "limit"),
            "context": bounded(raw.get("context"), 0, 0, CONTEXT_MAX, "context")}
    args.update(time_bounds(raw))
    return args


# ==================================================================== READ

def parse_read(raw):
    has_id = raw.get("id") not in (None, "")
    turns = [str(raw.get(k) or "").strip() for k in ("from_turn", "to_turn")]
    if has_id and any(turns):
        raise Refusal("bad_arguments", "name either `id` or a turn range, not both")
    if has_id:
        h = norm_id(raw.get("id"))
        if not h:
            raise Refusal("bad_arguments",
                          "`id` is `#` and 12 hex digits as the window shows it, or a full hash")
        return {"id": h}
    if not any(turns):
        raise Refusal("bad_arguments", "name an `id`, or `from_turn` and/or `to_turn`")
    first, last = turns[0] or turns[1], turns[1] or turns[0]
    return {"from_turn": first, "to_turn": last}


def entry_of(r, el):
    return {"id": short_id(r.get("hash")), "hash": r.get("hash"), "seq": r.get("seq"),
            "session_id": r.get("session_id"), "turn_id": r.get("turn_id"),
            "kind": r.get("kind"), "final": r.get("final"), "at": r.get("at"),
            "block": el}


def size_of(bodies):
    return sum(len(str(b or "")) for b in bodies)


def range_rows(args):
    """The wall from the first row of `from_turn` to the time of the last row
    of `to_turn`, in order (two columns, one operator each), at most one row
    more than `scan_budget`; the reader cuts it after the last row of
    `to_turn`. Inside one session the read is bounded by it too."""
    where = {"seq": {"gte": int(args["lo"])}, "at": {"lte": args["at_hi"]}}
    if args.get("session"):
        where["session_id"] = args["session"]
    return sel("wall", WALL_COLS, where, [("seq", "asc")], SCAN_BUDGET + 1)


def span_of(args, got):
    hi = int(args.get("hi") or 0)
    return [r for r in got if int(r.get("seq") or 0) <= hi]


# ================================================================= OUTLINE

def topic_of(value):
    """(movement, name) of one `topic` mark in the form OR-KY-71 writes --
    canonical JSON `{"movement": .., "name": ..}`, `name` empty when the memory
    section named none -- or None for any other value."""
    try:
        v = json.loads(str(value or ""))
    except Exception:
        return None
    if not isinstance(v, dict):
        return None
    movement = str(v.get("movement") or "").strip().lower()
    if movement not in MOVES:
        return None
    return movement, str(v.get("name") or "").strip()


def outline_answer(wall, marks, since, truncated):
    """Sessions oldest first; topics out of the `topic` marks (OR-KY-71): the
    open topic is the name of the newest mark with a name and no later `end`,
    a nameless `continue` or `end` belongs to it -- across sessions, too. A
    nameless `start` with nothing open opens a topic without a name. A topic
    shows `from_turn` only in the session its `start` stands in (null: it began
    earlier); only the entry of the topic still open at the end is `open`."""
    sessions, seen = {}, {}
    for r in wall:
        sid, turn, at = (str(r.get("session_id") or ""), str(r.get("turn_id") or ""),
                         str(r.get("at") or ""))
        s = sessions.get(sid)
        if s is None:
            s = sessions[sid] = {"session_id": sid, "first_turn": turn, "last_turn": turn,
                                 "first_at": at, "last_at": at, "turns": 0, "topics": []}
            seen[sid] = set()
        s["last_turn"], s["last_at"] = turn, at
        if turn not in seen[sid]:
            seen[sid].add(turn)
            s["turns"] += 1
    current = None
    for m in marks:
        t = topic_of(m.get("value"))
        if t is None:
            continue
        movement, name = t
        sid, turn = str(m.get("session_id") or ""), str(m.get("turn_id") or "")
        if current is None or (name and name != current["name"]):
            if not name and movement != "start":
                continue
            if current is not None and current["entry"] is not None:
                current["entry"]["open"] = False
            current = {"name": name or None, "sid": None, "entry": None}
        if current["sid"] != sid:
            if current["entry"] is not None:
                current["entry"]["open"] = False
            began = current["sid"] is None and movement == "start"
            entry = None
            if sid in sessions:
                entry = {"name": current["name"], "from_turn": turn if began else None,
                         "to_turn": turn, "open": True}
                sessions[sid]["topics"].append(entry)
            current["sid"], current["entry"] = sid, entry
        if current["entry"] is not None:
            current["entry"]["to_turn"] = turn
        if movement == "end":
            if current["entry"] is not None:
                current["entry"]["open"] = False
            current = None
    listed = list(sessions.values())
    omitted = max(0, len(listed) - OUTLINE_SESSIONS)
    out = {"sessions": listed[omitted:], "omitted_sessions": omitted,
           "truncated_scan": truncated}
    if since:
        out["since"] = since
    return out


# =================================================================== LANES
lane = str(hop.get("route") or "")
phase = str(ctx.get("cur_phase") or "")
op = str(hop.get("operation") or "")


def carry(name, args):
    return json.dumps({"tool": name, "args": args}, sort_keys=True)


def first_step(name, raw):
    """The first ledger read of a call whose arguments hold."""
    if name == "history_search":
        args = parse_search(raw)
        args.update(t0=now_ms(), scanned=0, total=0, hits=[])
        return lstore([("s-next", wall_page(args, None, min(PAGE_ROWS, SCAN_BUDGET)))],
                      "search-rows", call_id, carry(name, args))
    if name == "history_read":
        args = parse_read(raw)
        if "id" in args:
            h = args["id"]
            # No prefix operator in the store: the first hashes at or above
            # the prefix, in order, are the only ones that can start with it.
            where = {"hash": h} if len(h) == 64 else {"hash": {"gte": h}}
            return lstore([("r-cand", sel("blocks", ["hash"], where, [("hash", "asc")], 8))],
                          "read-id", call_id, carry(name, args))
        return lstore([("r-turns", sel("wall", ["seq", "session_id", "turn_id", "at"],
                                       {"turn_id": {"in": sorted({args["from_turn"],
                                                                  args["to_turn"]})}},
                                       [("seq", "asc")]))],
                      "read-turns", call_id, carry(name, args))
    args = time_bounds({"since": raw.get("since")})
    where = {"at": {"gte": args["since"]}} if args.get("since") else None
    return lstore([("o-wall", sel("wall", ["seq", "session_id", "turn_id", "at"], where,
                                  [("seq", "desc")], SCAN_BUDGET + 1)),
                   ("o-marks", sel("marks", ["seq", "session_id", "turn_id", "value"],
                                   {"kind": "topic"}, [("seq", "desc")], SCAN_BUDGET))],
                  "outline", call_id, carry(name, args))


if lane == "in_history_call":
    call = next((m for m in d.get("messages") or []
                 if isinstance(m, dict) and m.get("type") == "tool_call"), None) or {}
    call_id = str(hop.get("tool_call_id") or call.get("id") or "")
    name = str(hop.get("tool_name") or "")
    if not call_id:
        park("a history call without a call id -- dropped")
    if name not in ARGS:
        refuse(call_id, name, "unknown_tool",
               "this hive serves " + ", ".join(sorted(ARGS)))
    try:
        raw = json.loads(str(call.get("text") or "") or "{}")
    except Exception:
        raw = None
    if not isinstance(raw, dict):
        refuse(call_id, name, "bad_arguments", "the arguments are not one JSON object")
    try:
        emit([first_step(name, raw)])
    except Refusal as r:
        refuse(call_id, name, r.code, r.detail, r.extra)

if lane:
    park("unknown lane %r -- dropped" % lane)
if not op:
    park("a message with neither a lane nor a store answer -- dropped")

lg = legs(d)
if phase == "reread":
    if failed(lg):
        sys.stderr.write("curator/history: a reread mark was refused: %s\n"
                         % ", ".join(failed(lg)))
    emit([])

call_id = str(ctx.get("cur_call") or "")
try:
    carried = json.loads(str(ctx.get("cur_reason") or "") or "{}")
except Exception:
    carried = {}
name = str((carried or {}).get("tool") or "")
args = (carried or {}).get("args") or {}
if not call_id or name not in ARGS:
    park("store answer in phase %r without its call -- dropped" % phase)
if failed(lg):
    # The ledger refusing a read is this hive's failure, not the model's: it is
    # said here and answered there, so the round the call belongs to closes.
    sys.stderr.write("curator/history: ledger refused %s in phase %s\n"
                     % (", ".join(failed(lg)), phase))
    refuse(call_id, name, "ledger_error", "the ledger refused the read; try again later")

if phase == "search-rows":
    first = [r for r in rows(lg, "s-next") if inside(args, r)]
    if not first:
        finish_search(args)
    emit([page_bundle(args, first)])

if phase == "search-page":
    page = rows(lg, "s-page")
    later = [r for r in rows(lg, "s-next") if inside(args, r)]
    cut = scan_page(args, page, bodies_of(lg, "s-blocks"))
    if cut:
        finish_search(args, cut_by=cut)
    if not later:
        finish_search(args)
    if len(args["hits"]) >= args["limit"]:
        finish_search(args, stopped=True)
    if args["scanned"] >= SCAN_BUDGET:
        finish_search(args, cut_by="scan_budget")
    if now_ms() - int(args["t0"]) >= TIME_BUDGET_MS:
        finish_search(args, cut_by="time_budget")
    emit([page_bundle(args, later)])

if phase == "search-near":
    width = int(args.get("context") or 0)
    ops = near_ops(args["hits"], width)
    hashes = sorted({str(r.get("hash") or "") for cid, _ in ops for r in rows(lg, cid)})
    if not hashes:
        for hit in args["hits"]:
            hit["before"], hit["after"] = [], []
        emit([answer(call_id, name, search_payload(args))])
    # The rows once more beside their bodies (a row appended in between has no
    # body here and is left out).
    emit([lstore(ops + [("n-blocks", sel("blocks", ["hash", "body"], {"hash": {"in": hashes}}))],
                 "search-near-2", call_id, carry(name, args))])

if phase == "search-near-2":
    width = int(args.get("context") or 0)
    bodies = bodies_of(lg, "n-blocks")
    for i, hit in enumerate(args["hits"]):
        older = [r for r in rows(lg, "nb%d" % i) if str(r.get("hash") or "") in bodies]
        newer = [r for r in rows(lg, "na%d" % i) if str(r.get("hash") or "") in bodies]
        own = own_history(older + newer, bodies)
        older = [r for r in older if int(r.get("seq") or 0) not in own][:width]
        newer = [r for r in newer if int(r.get("seq") or 0) not in own][:width]
        hit["before"] = [neighbour(r, bodies) for r in reversed(older)]
        hit["after"] = [neighbour(r, bodies) for r in newer]
    emit([answer(call_id, name, search_payload(args))])

if phase == "read-id":
    h = str(args.get("id") or "")
    cands = sorted({str(r.get("hash") or "") for r in rows(lg, "r-cand")
                    if str(r.get("hash") or "").startswith(h)})
    if not cands:
        refuse(call_id, name, "not_found", "no block of this wall has the id #" + h[:12])
    turn = str(ctx.get("turn_id") or "")
    emit([lstore([("r-wall", sel("wall", WALL_COLS, {"hash": {"in": cands}}, [("seq", "asc")])),
                  ("r-blocks", sel("blocks", ["hash", "body"], {"hash": {"in": cands}}))]
                 + marks_reads(turn), "read-id-2", call_id, carry(name, args))])

if phase == "read-id-2":
    wall = rows(lg, "r-wall")
    on_wall = sorted({str(r.get("hash") or "") for r in wall})
    if not on_wall:
        # A hash the ledger holds but the wall never carried (a system leaf, a
        # summary, a window form) is not a block of this model's turns.
        refuse(call_id, name, "not_found",
               "no block of this wall has the id #" + str(args.get("id") or "")[:12])
    if len(on_wall) > 1:
        refuse(call_id, name, "ambiguous",
               "the id names more than one block; ask with a longer one",
               {"candidates": ["#" + c[:16] for c in on_wall]})
    h = on_wall[0]
    body = bodies_of(lg, "r-blocks").get(h) or ""
    size = len(body)
    if size > READ_BUDGET:
        refuse(call_id, name, "too_large",
               "the block is larger than the read budget; it is never shortened",
               {"size": size, "budget": READ_BUDGET})
    mine = [r for r in wall if str(r.get("hash") or "") == h]
    released = released_hashes(rows(lg, "r-rel"), [h])
    entry = entry_of(mine[0], element_of(body))
    entry["appearances"] = len(mine)
    entry["released"] = h in released
    out = [answer(call_id, name, {"blocks": [entry], "size": size})]
    ops = reread_ops(released, rows(lg, "r-mine"))
    if ops:
        out.append(lstore(ops, "reread", call_id, ""))
    emit(out)

if phase == "read-turns":
    found = rows(lg, "r-turns")
    first, last = str(args.get("from_turn") or ""), str(args.get("to_turn") or "")
    head = [r for r in found if str(r.get("turn_id") or "") == first]
    tail = [r for r in found if str(r.get("turn_id") or "") == last]
    missing = [t for t, rs in ((first, head), (last, tail)) if not rs]
    if missing:
        refuse(call_id, name, "not_found",
               "no turn of this wall has the id " + ", ".join(sorted(set(missing))))
    lo = min(int(r.get("seq") or 0) for r in head)
    hi = max(int(r.get("seq") or 0) for r in tail)
    if lo > hi:
        refuse(call_id, name, "bad_range", "`from_turn` lies after `to_turn` on the wall")
    sessions = sorted({str(r.get("session_id") or "") for r in head + tail})
    at_hi = max(str(r.get("at") or "") for r in tail)
    args = dict(args, lo=lo, hi=hi, at_hi=at_hi,
                session=sessions[0] if len(sessions) == 1 else "")
    emit([lstore([("r-range", range_rows(args))], "read-range", call_id, carry(name, args))])

if phase == "read-range":
    span = span_of(args, rows(lg, "r-range"))
    if len(span) > SCAN_BUDGET:
        refuse(call_id, name, "too_large",
               "the turn range holds more blocks than one read may; ask for fewer turns",
               {"block_count_at_least": len(span), "budget": READ_BUDGET})
    if not span:
        refuse(call_id, name, "not_found", "the turn range holds no block")
    hashes = sorted({str(r.get("hash") or "") for r in span})
    emit([lstore([("r-range", range_rows(args)),
                  ("r-chars", sel("blocks", ["hash", "chars"], {"hash": {"in": hashes}}))],
                 "read-range-2", call_id, carry(name, args))])

if phase == "read-range-2":
    span = span_of(args, rows(lg, "r-range"))
    chars = {str(r.get("hash") or ""): int(r.get("chars") or 0) for r in rows(lg, "r-chars")}
    raw = sum(chars.get(str(r.get("hash") or ""), 0) for r in span)
    if raw > RAW_FACTOR * READ_BUDGET:
        refuse(call_id, name, "too_large",
               "the turn range is many times larger than the read budget; ask for fewer turns",
               {"raw_size": raw, "budget": READ_BUDGET, "block_count": len(span)})
    hashes = sorted({str(r.get("hash") or "") for r in span})
    turn = str(ctx.get("turn_id") or "")
    emit([lstore([("r-range", range_rows(args)),
                  ("r-blocks", sel("blocks", ["hash", "body"], {"hash": {"in": hashes}}))]
                 + marks_reads(turn), "read-range-3", call_id, carry(name, args))])

if phase == "read-range-3":
    span = span_of(args, rows(lg, "r-range"))
    bodies = bodies_of(lg, "r-blocks")
    own = own_history(span, bodies)
    kept = [r for r in span if int(r.get("seq") or 0) not in own]
    size = size_of(bodies.get(str(r.get("hash") or ""), "") for r in kept)
    if size > READ_BUDGET:
        refuse(call_id, name, "too_large",
               "the turn range is larger than the read budget; it is never shortened",
               {"size": size, "budget": READ_BUDGET, "block_count": len(kept)})
    released = released_hashes(rows(lg, "r-rel"),
                               sorted({str(r.get("hash") or "") for r in kept}))
    entries = []
    for r in kept:
        e = entry_of(r, element_of(bodies.get(str(r.get("hash") or ""))))
        e["released"] = str(r.get("hash") or "") in released
        entries.append(e)
    out = [answer(call_id, name, {"blocks": entries, "size": size,
                                  "skipped_history": len(span) - len(kept),
                                  "from_turn": args.get("from_turn"),
                                  "to_turn": args.get("to_turn")})]
    ops = reread_ops(released, rows(lg, "r-mine"))
    if ops:
        out.append(lstore(ops, "reread", call_id, ""))
    emit(out)

if phase == "outline":
    wall = rows(lg, "o-wall")
    truncated = len(wall) > SCAN_BUDGET
    wall = list(reversed(wall[:SCAN_BUDGET]))
    marks = list(reversed(rows(lg, "o-marks")))
    emit([answer(call_id, name, outline_answer(wall, marks, args.get("since"), truncated))])

park("store answer in unknown phase %r -- dropped" % phase)
